corrected_code:
package contracts

import (
	"context"
	"gorm.io/gorm"
	"myapp/auth"
	"myapp/models"
)

type ContractService struct {
	DB *gorm.DB
}

func (s *ContractService) GetDocumentTemplate(ctx context.Context, docID string) (*models.ContractTemplate, error) {
	var tmpl models.ContractTemplate
	orgID := auth.OrgIDFromContext(ctx)

	err := s.DB.WithContext(ctx).
		Where("id = ? AND organization_id = ?", docID, orgID).
		First(&tmpl).Error
	if err != nil {
		return nil, err
	}

	return &tmpl, nil
}
